<form class="search-page-form mb-3"><div class="input-group input-group-lg"><input class="form-control" name="q" value="<?= e($query) ?>" placeholder="Search customer, job, invoice, quotation, asset, contract, item..."><button class="btn btn-primary">Search</button></div></form><div class="card-panel"><?php if(!$query): ?><div class="empty-state">Type a keyword or document number.</div><?php elseif(!$results): ?><div class="empty-state">No results for “<?= e($query) ?>”.</div><?php else: ?><?php foreach($results as $r): ?><a href="<?= url($r['url']) ?>" class="search-result"><span class="status-badge"><?= e($r['type']) ?></span><div><strong><?= e($r['title']) ?></strong><small><?= e($r['subtitle']??'') ?></small></div><i class="bi bi-arrow-right"></i></a><?php endforeach; ?><?php endif; ?></div>
